export const BODY: string = "\n<p>الصورة تحتوي أصلًا على لوحة ألوان تعمل. الضوء والأسطح والموضوع تآمروا لإنتاج ألوان تتناسب معًا، والمصمم الجيد يستطيع استعارة ذلك التناغم كاملًا.</p>\n<p>الجزء الصعب ليس إيجاد الألوان، بل اختيار أيها تستخدم وكم من كل منها وما الذي تتركه خارجًا، لتخدم اللوحة التصميم بدل أن تحاربه.</p>\n<p>يغطي هذا المقال سير العمل: من لوحة مستخرجة إلى نظام تصميم يعمل، مع القواعد والنسب والأخطاء التي تجعل لوحات الصور تفشل.</p>\n<h2 id=\"why-photos-make-good-palettes\">لماذا تعطي الصور لوحات جيدة</h2>\n<p>الصور تلتقط الألوان كما تظهر في العالم الحقيقي، بضوء حقيقي على أسطح حقيقية. هذه الألوان تتناغم أصلًا، لأن الضوء الذي أضاء المشهد كان نفسه لكلها.</p>\n<p>اللوحة المخترعة من الصفر لا تملك هذا الضمان. لونان مختاران منفصلين قد يتصادمان بطرق يصعب التنبؤ بها، بينما لونان من صورة أثبتا أصلًا أنهما يتعايشان. كما تحمل الصور مزاجًا: صورة غروب دافئة تعطي لوحة دافئة، وصورة محيط باردة تعطي لوحة باردة.</p>\n<h2 id=\"dominant-vs-accent\">الألوان المهيمنة مقابل ألوان التمييز</h2>\n<p>كل لوحة لها تسلسل هرمي. اللون المهيمن يغطي أكبر منطقة ويحدد النغمة، واللون الثانوي يدعمه، وألوان التمييز تظهر بكميات صغيرة لجذب العين.</p>\n<p>شارات النسبة المئوية في المستخرج تظهر التسلسل مباشرة. لون بنسبة 40 بالمئة مهيمن، ولون بنسبة 15 بالمئة ثانوي، ولون بنسبة 3 بالمئة تمييز. واحترم التسلسل في تصميمك: لوحة مستخدمة بنفس نسب الصورة ستبدو طبيعية لأنها تكرر التوازن الذي قبلته العين أصلًا.</p>\n<h2 id=\"the-60-30-10-rule\">قاعدة 60-30-10</h2>\n<p>قاعدة 60-30-10 هي أبسط طريقة لتطبيق لوحة صورة. أعطِ اللون المهيمن 60 بالمئة من المساحة، واللون الثانوي 30 بالمئة، ولون التمييز 10 بالمئة الباقية.</p>\n<p>ابدأ من نسب المستخرج وقرّبها نحو القاعدة. صورة بألوان 55 و30 و8 بالمئة قريبة أصلًا من المثالي، والقاعدة تُضفي طابعًا رسميًا على ما كانت الصورة تفعله أصلًا. والقاعدة تعمل لأنها تنشئ تسلسلًا واضحًا: العين تعرف ما هو خلفية وما هو محتوى وما هو تأكيد.</p>\n<h2 id=\"warm-vs-cool-harmony\">التناغم الدافئ مقابل البارد</h2>\n<p>الصور تميل إلى الدافئ أو البارد، واللوحة ترث ذلك الميل. صورة صحراء تعطي برتقاليًا وبنيًا دافئًا، بينما صورة شتاء تعطي أزرق ورماديًا باردًا.</p>\n<p>اللوحة التي تخلط ألوانًا دافئة وباردة يمكن أن تعمل، لكنها تحتاج قائدًا واضحًا. لوحة دافئة بتمييز بارد تبدو مقصودة، بينما لوحة مقسمة بالتساوي بين الدافئ والبارد تبدو مترددة. وراجع قيم الدرجة في مخرجات المستخرج: الألوان بدرجات قرب 0 إلى 60 دافئة، وقرب 180 إلى 260 باردة.</p>\n<h2 id=\"contrast-and-accessibility\">التباين وسهولة الوصول</h2>\n<p>لوحة جميلة قد تكون غير مقروءة. النص يحتاج تباينًا كافيًا مع خلفيته، ولوحات الصور لا تضمن ذلك وحدها.</p>\n<p>راجع كل زوج نص وخلفية في اللوحة للتباين. الألوان الأفتح والأظلم تمر عادة، بينما لونان متوسطا النغمة من الصورة نفسها يفشلان غالبًا. وHSL يساعد هنا: لونان بقيم إضاءة متباعدة جدًا يمران عادة في فحص التباين، بينما لونان بإضاءة متشابهة لا يمران بغض النظر عن درجتيهما.</p>\n<h2 id=\"from-palette-to-design-system\">من اللوحة إلى نظام التصميم</h2>\n<p>تتحول اللوحة إلى نظام تصميم عندما يحصل كل لون على دور. سمِّ العينات حسب عملها، مثل خلفية وسطح ورئيسي وثانوي وتمييز ونص، بدل تسميتها حسب لونها.</p>\n<p>الأدوار تجعل اللوحة قابلة للاستخدام من فريق. مطور يرى متغيرًا اسمه تمييز يعرف أين يستخدمه، بينما متغير اسمه برتقالي-3 يدعو إلى التخمين. وولّد الدرجات من الألوان الأساسية في HSL بتغيير الإضاءة فقط، واحفظ النظام كرموز تصميم.</p>\n<h2 id=\"mood-boards\">لوحات الإلهام من الصور</h2>\n<p>لوحة الإلهام مجموعة صور تشترك في إحساس، ولوحاتها يجب أن تتطابق معًا. استخرج لوحة من كل صورة وقارنها جنبًا إلى جنب.</p>\n<p>عندما تشترك اللوحات في نغمة مهيمنة أو درجة حرارة متشابهة، تبدو لوحة الإلهام متماسكة. وعندما تسحب في اتجاهات مختلفة، تبدو اللوحة مبعثرة، وربما تكون صورة واحدة هي الخارجة. واستخدم بطاقات لوحة المستخرج كلوحة الإلهام نفسها، فكل بطاقة تعرض الصورة مع عيناتها.</p>\n<h2 id=\"brand-palettes-from-photos\">لوحات العلامة التجارية من الصور</h2>\n<p>العلامات التجارية تبدأ غالبًا من صورة فوتوغرافية: بورتريه المؤسس أو صورة منتج أو مكان يهم الشركة. اللوحة المستخرجة من تلك الصورة تحمل قصة العلامة في ألوانها.</p>\n<p>لعمل العلامة التجارية، استخرج من أفضل نسخة من الصورة المصدر، ثم قلّم اللوحة إلى أربعة أو خمسة ألوان. لوحة العلامة تحتاج أن تكون لا تُنسى، ومجموعة من اثني عشر لونًا يصعب تذكرها. وتحقق من الألوان الرئيسية بمنتقي لون الصورة بعد الاستخراج، فالمنتقي يقرأ البكسل الدقيق.</p>\n<h2 id=\"seasonal-and-cultural-cues\">إشارات الموسم والثقافة</h2>\n<p>الألوان تحمل ارتباطات تتغير مع الموسم والثقافة. صورة خريف تعطي برتقاليًا وبنيًا يبدو جيدًا في أكتوبر وثقيلًا في مايو، بينما صورة ربيع تعطي أخضر فاتحًا وورديًا.</p>\n<p>عندما تختار صورة كمصدر لوحة، فكر في متى وأين سيُرى التصميم. لوحة حملة يجب أن تطابق موسمها، ولوحة علامة عالمية يجب أن تتجنب ألوانًا تحمل معاني سلبية في أسواق رئيسية. والمستخرج لا يستطيع الحكم على هذه الارتباطات؛ الحكم للمصمم الذي يعرف الجمهور واللحظة.</p>\n<h2 id=\"avoiding-muddy-palettes\">كيف تتجنب اللوحات العكرة</h2>\n<p>لوحات الصور تصبح عكرة عندما يتنافس كثير من الألوان متوسطة النغمة. صورة بخمسة ألوان بنية ورمادية متشابهة تنتج لوحة لا يبرز فيها شيء وكل شيء يبدو باهتًا.</p>\n<p>الحل هو الطرح. تخلص من النغمات الوسطى القريبة من بعضها، واحتفظ بالأفتح والأظلم، واحتفظ بتمييز واضح. اللوحة ذات التباين لوحة فيها حياة. وسبب آخر للعكارة هو خلط صور بإضاءة مختلفة: صورة دافئة وصورة باردة تنتج كل منهما لوحة جيدة، لكن دمجهما يعطي لوحة بلا درجة حرارة.</p>\n<h2 id=\"testing-a-palette\">كيف تختبر لوحة قبل الالتزام بها</h2>\n<p>اختبر اللوحة في تصميم حقيقي قبل الالتزام بها. اللوحة التي تبدو جيدة كعينات قد تفشل كصفحة، لأن العينات لا تظهر التباين أو التسلسل أو المقروئية.</p>\n<p>ابنِ نموذجًا سريعًا باللوحة مطبقة: ترويسة وفقرة وزر وبطاقة. إذا قُرئ النموذج جيدًا، فاللوحة تعمل. واختبر أيضًا بتدرج الرمادي: حوّل النموذج إلى أبيض وأسود وراجع هل ينجو التسلسل. واختبر أيضًا على شاشة هاتف، فالألوان تبدو مختلفة على الشاشات الصغيرة الساطعة.</p>\n<h2 id=\"palette-and-typography\">اللوحة والطباعة معًا</h2>\n<p>اللون والخط يعملان في زوج، واختيار اللوحة يقيّد الطباعة. اللوحة المزدحمة والملونة تحتاج خطًا هادئًا وبسيطًا، بينما اللوحة الرصينة تستطيع حمل خط أكثر تعبيرًا.</p>\n<p>لون النص يستحق نفس العناية التي تستحقها اللوحة نفسها. أظلم لون في اللوحة هو عادة لون النص، ويجب أن يكون داكنًا بما يكفي ليُقرأ براحة على أفتح خلفية. والروابط والعناصر التفاعلية تحتاج لونًا يبرز عن النص، ولون التمييز يؤدي هذا الدور عادة.</p>\n<h2 id=\"iterating-on-a-palette\">كيف تكرر على لوحة</h2>\n<p>اللوحة نادرًا ما تكون صحيحة في الاستخراج الأول. عامل اللوحة الأولى كمسودة: استخدمها في نموذج، ولاحظ ما يفشل، واستخرج مجددًا بصورة مختلفة أو عدد عينات مختلف.</p>\n<p>احفظ الإصدارات. لوحة كانت خاطئة لموقع قد تكون صحيحة لملصق، والإصدار الذي تخلصت منه قد يصبح الإجابة لتكليف لاحق. وكرر بخطوات صغيرة: غيّر لونًا واحدًا في كل مرة، أو غيّر الكمية في واحد، لتستطيع قول أي تغيير حسّن النتيجة وأيها أساءها.</p>\n<h2 id=\"palettes-for-data-visualization\">لوحات لتصور البيانات</h2>\n<p>الرسوم البيانية تحتاج لوحات بمنطق مختلف عن التصاميم. كل سلسلة بيانات تحتاج لونًا مميزًا عن غيره بنظرة واحدة، ويجب أن تبقى اللوحة مقروءة عند تصغير الرسم.</p>\n<p>استخرج لوحة من صورة واستخدمها لرسم بياني فقط بعد مراجعة الألوان معًا. لونان يبدوان مختلفين كعينات قد يبدوان متطابقين كخطي رسم رفيعين. وللبيانات الفئوية، اختر ألوانًا بدرجات متباعدة جدًا. وللبيانات المتسلسلة، استخدم درجة واحدة بإضاءة متغيرة.</p>\n<h2 id=\"quick-reference\">مرجع سريع: سير عمل لوحة الصورة</h2>\n<p>استخرج من صورة تحبها، واقرأ النسب المئوية، وطبّق قاعدة 60-30-10، وراجع التباين للنص، وعيّن لكل لون دورًا قبل بناء أي شيء.</p>\n<p>قلّم المكررات، وأنقذ التمييزات المفقودة بالقطارة، واختبر اللوحة في تصميم حقيقي وبتدرج الرمادي وعلى هاتف قبل الالتزام بها.</p>\n<p>لوحة الصورة تعمل لأن الألوان أثبتت أصلًا أنها تتناسب معًا. عملك هو اختيارها وتنسيبها وتسميتها، لا اختراعها من الصفر.</p>\n<p>لاستخراج اللوحة، استخدم <a href=\"/ar/istikraj-lauhat-alwan-min-as-sura/\">مستخرج لوحة ألوان الصورة</a>، ولبكسلات منفردة دقيقة استخدم <a href=\"/ar/muntqi-alwan-as-sura/\">منتقي لون الصورة</a>. وللسياق الكامل، اقرأ <a href=\"/ar/blog/kayfiyya-istikraj-lauhat-alwan-min-as-sura/\">كيف تستخرج لوحة ألوان من صورة</a> و<a href=\"/ar/blog/dalil-istikraj-lauhat-alwan-min-as-suwar/\">مستخرج لوحة الألوان: الدليل الكامل</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما هي قاعدة 60-30-10 للوحات الألوان؟","answer":"إنها قاعدة تنسيب: اللون المهيمن يشغل نحو 60 بالمئة من المساحة، واللون الثانوي 30 بالمئة، ولون التمييز 10 بالمئة. القاعدة تنشئ تسلسلًا بصريًا واضحًا لتعرف العين ما هو خلفية وما هو محتوى وما هو تأكيد."},{"question":"كم لونًا يجب أن تحمل لوحة علامة تجارية؟","answer":"أربعة إلى ستة هو النطاق المعتاد. يكفي ذلك لخلفية ورئيسي وثانوي وتمييز ولون نص، دون أن يصبح صعب التذكر. أكثر من ستة يصبح صعب الاستخدام باتساق لفريق."},{"question":"هل أستخدم الألوان المستخرجة كما هي أم أضبطها؟","answer":"اضبطها، فالاستخراج يعطيك نقطة بداية لا إجابة نهائية. غيّر درجة قليلًا لملاءمة العلامة، أو ارفع تشبع تمييز باهت، أو عتّم لون نص للتباين. الصورة مصدر إلهام لا قيد."},{"question":"هل يمكن أن تعمل لوحة صورة لموضوع الوضع الداكن؟","answer":"نعم مع العكس: خذ أظلم ألوان الصورة كخلفيات للوضع الداكن، واستخدم أفتح الألوان للنص. ألوان التمييز تنتقل مباشرة غالبًا. واختبر اللوحة في الوضعين قبل الالتزام بها."},{"question":"ماذا أفعل عندما لا تحمل اللوحة المستخرجة لون تمييز جيدًا؟","answer":"استعره، فاستخدم القطارة لأخذ عينة من تفصيل حي صغير فاته المستخرج، أو أدخل لونًا مكملًا من عجلة الألوان مقابل الدرجة المهيمنة. التمييز لا يجب أن يأتي من الصورة نفسها."},{"question":"كيف أبقي لوحة صورة متسقة في موقع ويب كامل؟","answer":"احفظ اللوحة كخصائص CSS مخصصة أو رموز تصميم، وأشر إلى المتغيرات في كل مكان بدل لصق أكواد HEX. بهذا يحدّث تغيير واحد الموقع كله. ووثّق أدوار كل لون في دليل العلامة."}];
